    <script type="module">
    /* ======== 状态栏主逻辑 ======== */

    /* 精神状态描述映射 */
    function getMentalDesc(val) {
        if (val <= -61) return '重度抑郁';
        if (val <= -31) return '抑郁低谷';
        if (val <= -1) return '低落波动';
        if (val === 0) return '基线平稳';
        if (val <= 30) return '轻度活跃';
        if (val <= 60) return '躁狂前兆';
        return '躁狂爆发';
    }

    /* 理智值描述映射 */
    function getSanityDesc(val) {
        if (val >= 80) return '秩序稳固';
        if (val >= 60) return '裂隙初现';
        if (val >= 40) return '灰色挣扎';
        if (val >= 20) return '原则崩塌边缘';
        return '临界崩溃';
    }

    /* 好感度阶段描述映射 */
    function getLoveDesc(val) {
        if (val < 20) return '无菌排斥';
        if (val < 46) return '样本观察';
        if (val < 71) return '灰色默契';
        if (val < 91) return '原则的裂缝';
        return '不可替代的例外';
    }

    /* 信任阶段描述映射 */
    function getTrustDesc(val) {
        if (val < 20) return '零信任';
        if (val < 46) return '有限信任';
        if (val < 71) return '条件信任';
        if (val < 91) return '深层信任';
        return '绝对信任';
    }

    /* 填充数据 */
    function populateReport() {
        const all_variables = getAllVariables();

        /* 安全获取所有变量 */
        const sanity = _.get(all_variables, 'stat_data.SanityOfLi', 100);
        const love = _.get(all_variables, 'stat_data.LoveForEthan', 0);
        const trust = _.get(all_variables, 'stat_data.TrustForEthan', 0);
        const mental = _.get(all_variables, 'stat_data.EthanMentalState', 0);
        const stage = _.get(all_variables, 'stat_data.RelationshipStage', '陌生人');
        const timeVal = _.get(all_variables, 'stat_data.Time', '——');

        /* 更新时间 */
        $('#report-time-value').text(timeVal);

        /* ---- 理智值 ---- */
        $('#val-sanity').text(sanity + ' / 100');
        const sanityPct = Math.min(100, Math.max(0, sanity));
        $('#bar-sanity').css('width', sanityPct + '%');
        $('#desc-sanity').text(getSanityDesc(sanity));

        /* 理智低时变色 */
        if (sanity < 40) {
            $('#val-sanity').css('color', '#8a5a4a');
        } else {
            $('#val-sanity').css('color', '#5c6b50');
        }

        /* ---- 好感度 ---- */
        $('#val-love').text(love + ' / 100');
        const lovePct = Math.min(100, Math.max(0, love));
        $('#bar-love').css('width', lovePct + '%');
        $('#desc-love').text(getLoveDesc(love));

        /* ---- 信任值 ---- */
        $('#val-trust').text(trust + ' / 100');
        const trustPct = Math.min(100, Math.max(0, trust));
        $('#bar-trust').css('width', trustPct + '%');
        $('#desc-trust').text(getTrustDesc(trust));

        /* ---- 精神状态（双向条） ---- */
        const mentalAbs = Math.abs(mental);
        const mentalPctHalf = Math.min(50, (mentalAbs / 100) * 50);
        const $mentalFill = $('#bar-mental-fill');

        if (mental >= 0) {
            $mentalFill.css({
                'left': '50%',
                'width': mentalPctHalf + '%'
            });
            $mentalFill.removeClass('bar-mental-neg').addClass('bar-mental-pos');
        } else {
            $mentalFill.css({
                'left': (50 - mentalPctHalf) + '%',
                'width': mentalPctHalf + '%'
            });
            $mentalFill.removeClass('bar-mental-pos').addClass('bar-mental-neg');
        }

        const mentalSign = mental > 0 ? '+' : '';
        $('#val-mental').text(mentalSign + mental);
        $('#desc-mental').text(getMentalDesc(mental));

        /* 极端状态变色 */
        if (mental <= -61 || mental >= 61) {
            $('#val-mental').css('color', '#8a4a4a');
        } else {
            $('#val-mental').css('color', '#5c5040');
        }

        /* ---- 相处阶段 ---- */
        $('#stage-tag-text').text(stage);

        /* 阶段指示点颜色 */
        const stageColors = {
            '陌生人': '#a0a0a0',
            '熟人': '#a09070',
            '挚友': '#80a080',
            '搭档': '#7090a0',
            '恋人': '#b08080',
            '劲敌': '#8a5050'
        };
        $('#stage-dot').css('background', stageColors[stage] || '#a09080');
    }

    /* 初始化 */
    async function init() {
        await waitGlobalInitialized('Mvu');
        populateReport();
    }

    $(errorCatched(init));
    </script>
