    <script type="module">
    /* ===== 精神状态阶段映射 ===== */
    function getMentalStage(val) {
        if (val <= -61) return '重度抑郁期';
        if (val <= -31) return '抑郁低谷';
        if (val <= -1) return '低落波动';
        if (val === 0) return '基线平稳';
        if (val <= 30) return '轻度活跃';
        if (val <= 60) return '躁狂前兆';
        return '躁狂爆发';
    }

    /* ===== 医嘱备注映射 ===== */
    function getMedicalNote(stage) {
        const notes = {
            '重度抑郁期': {
                lines: [
                    '建议陪伴时长：24h 持续看护',
                    '建议措施：移除利器，防止自伤行为',
                    '禁止独处，必要时联系紧急联络人',
                    '诊所运转移交助手全权负责'
                ]
            },
            '抑郁低谷': {
                lines: [
                    '建议陪伴时长：每日不少于 4h',
                    '建议措施：确保基本饮食摄入',
                    '减少高难度手术排期',
                    '允许安静陪伴，勿强制交流'
                ]
            },
            '低落波动': {
                lines: [
                    '建议陪伴时长：每日 1~2h 自然接触',
                    '建议措施：维持日常作息节奏',
                    '可安排轻度机械改装等转移活动',
                    '留意自毁念头但勿过度干预'
                ]
            },
            '基线平稳': {
                lines: [
                    '建议陪伴时长：顺其自然',
                    '建议措施：珍惜窗口期，维持正常互动',
                    '可适当推进深层沟通',
                    '注意监测状态波动方向'
                ]
            },
            '轻度活跃': {
                lines: [
                    '建议陪伴时长：常规社交频率',
                    '建议措施：状态良好，可正常合作',
                    '留意精力水平是否持续攀升',
                    '如睡眠低于 5h 需提高警惕'
                ]
            },
            '躁狂前兆': {
                lines: [
                    '建议陪伴时长：密切关注，随时待命',
                    '建议措施：限制高风险活动（飙车、连续手术）',
                    '减少刺激性互动与对抗',
                    '预备应急镇静方案'
                ]
            },
            '躁狂爆发': {
                lines: [
                    '建议陪伴时长：全程看护直至状态回落',
                    '建议措施：必要时进行物理约束',
                    '信息素压制可作为紧急手段',
                    '⚠ 身份暴露风险极高，注意信息素波动'
                ]
            }
        };
        return notes[stage] || notes['基线平稳'];
    }

    /* ===== 关系阶段定义映射 ===== */
    function getStageDef(stage) {
        const defs = {
            '陌生人': '尚未建立实质联系。彼此只是各自世界中模糊的轮廓。',
            '熟人': '多次接触后建立基本认知，关系停留在功能性表面。',
            '挚友': '超越公事的私人信任。愿意为对方分担情感负担。',
            '搭档': '稳定的合作默契已成形。彼此依赖对方的专业能力。',
            '恋人': '确认了超越一切的情感关系。存在明确的亲密行为与承诺。',
            '劲敌': '重大分歧或背叛导致关系破裂。从亲密转为对立，但羁绊未断。'
        };
        return defs[stage] || '——';
    }

    /* ===== 格式化当前时间 ===== */
    function getFormattedTime() {
        const now = new Date();
        const y = now.getFullYear();
        const m = String(now.getMonth() + 1).padStart(2, '0');
        const d = String(now.getDate()).padStart(2, '0');
        const h = String(now.getHours()).padStart(2, '0');
        const min = String(now.getMinutes()).padStart(2, '0');
        return y + '.' + m + '.' + d + '  ' + h + ':' + min;
    }

    /* ===== 主初始化 ===== */
    async function init() {
        await waitGlobalInitialized('Mvu');

        const all_variables = getAllVariables();

        /* 读取变量 */
        const sanity = _.get(all_variables, 'stat_data.SanityOfLi', 100);
        const love = _.get(all_variables, 'stat_data.LoveForEthan', 0);
        const trust = _.get(all_variables, 'stat_data.TrustForEthan', 0);
        const mental = _.get(all_variables, 'stat_data.EthanMentalState', 0);
        const stage = _.get(all_variables, 'stat_data.RelationshipStage', '陌生人');

        /* 时间 */
        $('#dossier-time').text(getFormattedTime());

        /* 李哲远 - 理智值 */
        $('#val-sanity').text(sanity + ' / 100');
        $('#bar-sanity').css('width', Math.max(0, Math.min(100, sanity)) + '%');

        /* 李哲远 - 好感度 */
        $('#val-love').text(love + ' / 100');
        $('#bar-love').css('width', Math.max(0, Math.min(100, love)) + '%');

        /* 李哲远 - 信任值 */
        $('#val-trust').text(trust + ' / 100');
        $('#bar-trust').css('width', Math.max(0, Math.min(100, trust)) + '%');

        /* Ethan - 精神状态 */
        $('#val-mental').text(mental);
        /* 将 -100~100 映射到 0%~100% */
        const mentalPercent = ((mental + 100) / 200) * 100;
        $('#mental-thumb').css('left', Math.max(0, Math.min(100, mentalPercent)) + '%');

        /* 阶段显示 */
        const mentalStage = getMentalStage(mental);
        $('#mental-stage-text').text(mentalStage);

        /* 医嘱 */
        const noteData = getMedicalNote(mentalStage);
        let noteHtml = '';
        $.each(noteData.lines, function(i, line) {
            noteHtml += '<div class="medical-note-line">' + line + '</div>';
        });
        $('#medical-note-content').html(noteHtml);

        /* 关系阶段 */
        $('#rel-stage-value').text(stage);
        $('#rel-stage-def').text(getStageDef(stage));

        /* 序列号 */
        const serial = 'JZ-' + String(Math.floor(Math.random() * 90000) + 10000);
        $('#dossier-serial').text(serial);
    }

    $(errorCatched(init));
    </script>
