    /* 依据数值返回档位描述 */
    function levelOf(value, table) {
        for (const item of table) {
            if (value <= item.max) return item;
        }
        return _.last(table);
    }

    /* 依据百分比返回进度条配色类 */
    function fillClass(percent) {
        if (percent < 34) return 'mc-fill lv-low';
        if (percent < 71) return 'mc-fill lv-mid';
        return 'mc-fill lv-high';
    }

    function populateCharacterData() {
