        const love = _.clamp(Number(_.get(all_variables, 'stat_data.LoveForEthan', 0)) || 0, 0, 100);
        const trust = _.clamp(Number(_.get(all_variables, 'stat_data.TrustForEthan', 0)) || 0, 0, 100);
        const mind = _.clamp(Number(_.get(all_variables, 'stat_data.EthanMentalState', 0)) || 0, -100, 100);
