<script type="module">
/* ---------- 工具 ---------- */
const CMT = '/' + '/';
const PROMPT = 'wu5@ghostnet';

function pick(v, d) {
  if (_.isArray(v)) { return _.isNil(v[0]) ? d : v[0]; }
  return _.isNil(v) ? d : v;
}
function num(v, d) {
  const n = Number(pick(v, d));
  return _.isFinite(n) ? n : d;
}

/* 生成 ASCII 进度条（0~100） */
function makeBar($slot, percent, cells) {
  const p = _.clamp(percent, 0, 100);
  const filled = Math.round((p / 100) * cells);
  let f = '', e = '';
  for (let i = 0; i < filled; i++) { f += '█'; }
  for (let i = filled; i < cells; i++) { e += '░'; }
  $slot.empty()
    .append($('<span></span>').addClass('brk').text('['))
    .append($('<span></span>').addClass('bar-f').text(f))
    .append($('<span></span>').addClass('bar-e').text(e))
    .append($('<span></span>').addClass('brk').text(']'));
}

/* 生成双极性 ASCII 条（-100~100） */
function makeBipolar($slot, value, half) {
  const v = _.clamp(value, -100, 100);
  const n = Math.round((Math.abs(v) / 100) * half);
  let left = '', right = '';
  for (let i = 0; i < half; i++) {
    const dist = half - i;
    left += (v < 0 && dist <= n) ? '█' : '░';
  }
  for (let i = 0; i < half; i++) {
    const dist = i + 1;
    right += (v > 0 && dist <= n) ? '█' : '░';
  }
  const negCls = 'c-cyn', posCls = (v > 60 ? 'c-red' : 'c-amb');
  $slot.empty()
    .append($('<span></span>').addClass('brk').text('['))
    .append($('<span></span>').addClass(v < 0 ? negCls : 'bar-e').text(left))
    .append($('<span></span>').addClass('c-gry').text('|'))
    .append($('<span></span>').addClass(v > 0 ? posCls : 'bar-e').text(right))
    .append($('<span></span>').addClass('brk').text(']'));
}

/* ---------- 分级 ---------- */
function tierLove(v) {
  if (v <= 19) { return '无菌排斥'; }
  if (v <= 45) { return '样本观察'; }
  if (v <= 70) { return '灰色默契'; }
  if (v <= 90) { return '原则的裂缝'; }
  return '不可替代的例外';
}
function tierSanity(v) {
  if (v <= 19) { return '临界崩溃'; }
  if (v <= 39) { return '原则崩塌边缘'; }
  if (v <= 59) { return '灰色挣扎'; }
  if (v <= 79) { return '裂隙初现'; }
  return '秩序稳固';
}
function tierTrust(v) {
  if (v <= 19) { return '零信任'; }
  if (v <= 45) { return '有限信任'; }
  if (v <= 70) { return '条件信任'; }
  if (v <= 90) { return '深层信任'; }
  return '绝对信任';
}
function tierMental(v) {
  if (v <= -61) { return '重度抑郁期'; }
  if (v <= -31) { return '抑郁低谷'; }
  if (v <= -1) { return '低落波动'; }
  if (v === 0) { return '基线平稳'; }
  if (v <= 30) { return '轻度活跃'; }
  if (v <= 60) { return '躁狂前兆'; }
  return '躁狂爆发';
}

/* ---------- 注释行 ---------- */
function noteSanity(v) {
  if (v <= 19) { return { c: 'crit', t: CMT + ' CRITICAL: rational shell collapsed — 理性外壳已失效，禁止单独出勤' }; }
  if (v <= 39) { return { c: 'crit', t: CMT + ' WARNING: sanity dropping — 检测到手部震颤 / 反常沉默 / 冲动决策风险' }; }
  if (v <= 59) { return { c: 'warn', t: CMT + ' CAUTION: 失眠 + 过度工作，判断力衰减中，建议强制休眠 6h' }; }
  if (v <= 79) { return { c: 'info', t: CMT + ' notice: 对程序正义的第一道裂缝已记录，仍在可控区间' }; }
  return { c: 'info', t: CMT + ' status: nominal — 程序正义模块运行正常' };
}
function noteMental(v) {
  if (v <= -61) { return { c: 'crit', t: CMT + ' CRITICAL: 自残倾向标记，诊所运行权限已移交 [小五]' }; }
  if (v <= -31) { return { c: 'warn', t: CMT + ' WARNING: 手术精度下降 12%，烟量超阈值，进食记录缺失' }; }
  if (v >= 61) { return { c: 'crit', t: CMT + ' ALERT: manic overflow — 通宵未眠，判断力受损，高危行为概率↑' }; }
  if (v >= 31) { return { c: 'warn', t: CMT + ' WARNING: 睡眠 <3h，思维加速，检测到飙车 / 连台手术倾向' }; }
  if (v <= -1) { return { c: 'info', t: CMT + ' notice: 灰调运行，黑色幽默尖刻度上升' }; }
  if (v === 0) { return { c: 'info', t: CMT + ' status: baseline — 罕见平稳，空洞感常驻后台进程' }; }
  return { c: 'info', t: CMT + ' status: 精力良好，调情模块 online' };
}
function noteTrust(v) {
  if (v <= 19) { return { c: 'warn', t: CMT + ' policy: 所有来自 target 的输入需交叉验证 [cross-check: ON]' }; }
  if (v <= 45) { return { c: 'info', t: CMT + ' scope: 仅限医术 / 地下情报领域，私人层面 access denied' }; }
  if (v <= 70) { return { c: 'info', t: CMT + ' scope: 案件协作可依赖，后背授权 pending' }; }
  if (v <= 90) { return { c: 'info', t: CMT + ' scope: 后背已授权，接受其不完美的表达方式' }; }
  return { c: 'info', t: CMT + ' scope: unconditional — 优先级高于体制' };
}
function noteLove(v) {
  if (v >= 91) { return { c: 'warn', t: CMT + ' EXCEPTION: unhandled — 原则集合中唯一未被捕获的例外' }; }
  if (v >= 71) { return { c: 'info', t: CMT + ' anomaly: 检测到主动铺设合法路径 + 隐性占有欲信号' }; }
  if (v >= 46) { return { c: 'info', t: CMT + ' access: 私人领域已开放，脆弱面 partially exposed' }; }
  if (v >= 20) { return { c: 'info', t: CMT + ' mode: 样本观察中，职业性好奇 > 排斥反应' }; }
  return { c: 'info', t: CMT + ' mode: 无菌隔离，礼貌疏离协议生效' };
}

/* ---------- 关系链 ---------- */
function renderStage($slot, stage) {
  const chain = ['陌生人', '熟人', '挚友', '搭档', '恋人'];
  $slot.empty();
  _.forEach(chain, function (s, i) {
    if (i > 0) { $slot.append($('<span></span>').addClass('c-gry').text(' › ')); }
    const on = (s === stage);
    $slot.append($('<span></span>').addClass('node' + (on ? ' on' : '')).text(on ? '[' + s + ']' : ' ' + s + ' '));
  });
  $slot.append($('<span></span>').addClass('c-gry').text('   ⟂ '));
  const hostile = (stage === '劲敌');
  $slot.append($('<span></span>').addClass('node' + (hostile ? ' hostile' : '')).text(hostile ? '[劲敌]' : ' 劲敌 '));
}

/* ---------- 打字机 ---------- */
function typeInto($el, text, speed, done) {
  let i = 0;
  $el.text('');
  function step() {
    i += 1;
    $el.text(text.slice(0, i));
    if (i < text.length) { setTimeout(step, speed); }
    else if (done) { done(); }
  }
  setTimeout(step, speed);
}

/* ---------- 队列 ---------- */
function runQueue(tasks) {
  let idx = 0;
  function next() {
    if (idx >= tasks.length) { return; }
    const t = tasks[idx];
    idx += 1;
    t(next);
  }
  next();
}

/* ---------- 主流程 ---------- */
function boot() {
  const all_variables = getAllVariables();

  const love = _.clamp(num(_.get(all_variables, 'stat_data.LoveForEthan', 0), 0), 0, 100);
