  $('.qblk').addClass('hidden');
  $('#boot-lines').empty();
  $('.note').removeClass('warn crit info').text('');

  const bootLines = [
    { t: 'ghostnet secure shell v2.7.1  ' + CMT + ' 未注册终端 · 流量已洗白', c: 'hl' },
    { t: 'authenticating ......... ok   user=wu5  alias=林', c: 'ok' },
    { t: 'mounting /dev/observation  [' + '█'.repeat(14) + '] 100%', c: 'ok' },
    { t: 'targets locked: [ LI_ZHEYUAN ] [ ETHAN ]   sync@' + ts, c: '' }
  ];

  const tasks = [];

  _.forEach(bootLines, function (ln) {
    tasks.push(function (next) {
      $('#boot-lines').append($('<div></div>').addClass(ln.c).text(ln.t));
      setTimeout(next, 130);
    });
  });

  /* 单条查询的通用任务 */
  function pushQuery(blk, cmdText, render, note) {
    tasks.push(function (next) {
      $('#blk-' + blk).removeClass('hidden');
      typeInto($('#cmd-' + blk), cmdText, 14, function () {
        const frames = ['|', '/', '-', '\\'];
