          clearInterval(iv);
          $sp.text('');
          render();
          if (note) {
            $('#note-' + blk).addClass(note.c).text(note.t);
          }
          setTimeout(next, 150);
        }, 380);
      });
    });
  }

  pushQuery('stage', 'query --link=LiZheyuan::Ethan --field=relationship_stage', function () {
    renderStage($('#out-stage'), stage);
    $('#val-stage').text(stage);
  }, {
    c: (stage === '劲敌' ? 'crit' : 'info'),
    t: (stage === '劲敌'
      ? CMT + ' ALERT: link inverted — 羁绊未断，通讯转为对抗模式'
      : CMT + ' link integrity: 阶段跃迁需叙事触发事件，不接受数值自动提升')
  });

  pushQuery('love', 'query --target=LiZheyuan --field=love_for_ethan', function () {
    makeBar($('#out-love'), love, 20);
    $('#val-love').text(_.padStart(love, 3, ' ') + '/100');
    $('#tier-love').text(':: ' + tierLove(love));
  }, noteLove(love));

  pushQuery('trust', 'query --target=LiZheyuan --field=trust', function () {
    makeBar($('#out-trust'), trust, 20);
    $('#val-trust').text(_.padStart(trust, 3, ' ') + '/100');
    $('#tier-trust').text(':: ' + tierTrust(trust));
  }, noteTrust(trust));

  pushQuery('sanity', 'query --target=LiZheyuan --field=sanity --verbose', function () {
    makeBar($('#out-sanity'), sanity, 20);
    $('#val-sanity').text(_.padStart(sanity, 3, ' ') + '/100');
    $('#tier-sanity').text(':: ' + tierSanity(sanity));
  }, noteSanity(sanity));

  pushQuery('mental', 'query --target=Ethan --field=mental_state --scale=bipolar', function () {
    makeBipolar($('#out-mental'), mental, 11);
    $('#val-mental').text(_.padStart((mental > 0 ? '+' : '') + mental, 4, ' ') + '/100');
    $('#tier-mental').text(':: ' + tierMental(mental));
  }, noteMental(mental));

  /* 收尾 */
  tasks.push(function (next) {
    $('#blk-eof').removeClass('hidden');
    $('#eof-line').text(CMT + ' 5 records dumped · session kept alive · ^C to detach');
    next();
  });

  runQueue(tasks);
}

async function init() {
  await waitGlobalInitialized('Mvu');
  boot();
  $('#term-rerun').on('click', errorCatched(boot));
}

$(errorCatched(init));
</script>
