    <script type="module">
    /* 将任意输入转换为指定范围内的有限数值 */
    function clampTerminalNumber(value, minimum, maximum, fallback) {
        const parsedValue = Number(value);
        const safeValue = Number.isFinite(parsedValue) ? parsedValue : fallback;
        return _.clamp(safeValue, minimum, maximum);
    }

    /* 获取李哲远理智状态描述 */
    function getSanityDescription(value) {
        if (value >= 80) {
            return 'ORDER_STABLE';
        }
        if (value >= 60) {
            return 'FRACTURE_DETECTED';
        }
        if (value >= 40) {
            return 'GRAY_STRUGGLE';
        }
        if (value >= 20) {
            return 'PRINCIPLE_FAILURE_RISK';
        }
        return 'CRITICAL_COLLAPSE';
    }

    /* 获取Ethan好感状态描述 */
    function getLoveDescription(value) {
        if (value >= 91) {
            return 'IRREPLACEABLE_EXCEPTION';
        }
        if (value >= 71) {
            return 'PRINCIPLE_BREACH';
        }
        if (value >= 46) {
            return 'GRAY_TACIT_AGREEMENT';
        }
        if (value >= 20) {
            return 'SPECIMEN_OBSERVATION';
        }
        return 'STERILE_REJECTION';
    }

    /* 获取Ethan信任状态描述 */
    function getTrustDescription(value) {
        if (value >= 91) {
            return 'ABSOLUTE_TRUST';
        }
        if (value >= 71) {
            return 'DEEP_TRUST';
        }
        if (value >= 46) {
            return 'CONDITIONAL_TRUST';
        }
        if (value >= 20) {
            return 'LIMITED_TRUST';
        }
        return 'ZERO_TRUST';
    }

    /* 获取Ethan精神状态描述 */
    function getMentalDescription(value) {
        if (value <= -61) {
            return 'SEVERE_DEPRESSION';
        }
        if (value <= -31) {
            return 'DEPRESSIVE_LOW';
        }
        if (value <= -1) {
            return 'LOW_FLUCTUATION';
        }
        if (value === 0) {
            return 'BASELINE_STABLE';
        }
        if (value <= 30) {
            return 'MILDLY_ACTIVE';
        }
        if (value <= 60) {
            return 'MANIC_PRODROME';
        }
        return 'MANIC_OUTBREAK';
    }

    /* 根据数值生成终端警告 */
    function getSanityWarning(value, prefix) {
        if (value < 20) {
            return prefix + ' alert: sanity critical; rational shell unavailable';
        }
        if (value < 40) {
            return prefix + ' warning: sanity dropping; principle failure imminent';
        }
        if (value < 60) {
            return prefix + ' notice: abnormal stress response detected';
        }
        return prefix + ' integrity check: cognition within operational range';
    }

    /* 根据精神状态生成终端警告 */
    function getMentalWarning(value, prefix) {
        if (value <= -61) {
            return prefix + ' alert: severe depressive episode; self-harm risk elevated';
        }
        if (value <= -31) {
            return prefix + ' warning: motor response and surgical precision degraded';
        }
        if (value >= 61) {
            return prefix + ' alert: manic outbreak; destructive behavior probable';
        }
        if (value >= 31) {
            return prefix + ' warning: sleep deficit and risk appetite increasing';
        }
        return prefix + ' observation: subject remains inside functional threshold';
    }

    /* 更新警告文本样式 */
    function updateWarningStyle(elementId, text, severity) {
        const $element = $('#' + elementId);
        $element
            .removeClass('warning danger')
            .text(text);

        if (severity === 'danger') {
            $element.addClass('danger');
        } else if (severity === 'warning') {
            $element.addClass('warning');
        }
    }

    /* 渲染全部MVU状态数据 */
    function populateCharacterData() {
        const all_variables = getAllVariables();
        const characterData = all_variables.stat_data;

        const sanityValue = clampTerminalNumber(
            _.get(all_variables, 'stat_data.SanityOfLi', 100),
            0,
            100,
            100
        );

        const loveValue = clampTerminalNumber(
            _.get(all_variables, 'stat_data.LoveForEthan', 0),
            0,
            100,
            0
        );

        const trustValue = clampTerminalNumber(
            _.get(all_variables, 'stat_data.TrustForEthan', 0),
            0,
            100,
            0
        );

        const relationshipValue = String(
            _.get(all_variables, 'stat_data.RelationshipStage', '陌生人')
        );

        const mentalValue = clampTerminalNumber(
            _.get(all_variables, 'stat_data.EthanMentalState', 0),
            -100,
            100,
            0
        );

        const mentalPercentage = ((mentalValue + 100) / 200) * 100;
        const commentPrefix = '/' + '/';

        $('#terminal-sanity-value').text(sanityValue + ' / 100');
        $('#terminal-sanity-state').text(getSanityDescription(sanityValue));
        $('#terminal-sanity-bar').css('width', sanityValue + '%');

        $('#terminal-love-value').text(loveValue + ' / 100');
        $('#terminal-love-state').text(getLoveDescription(loveValue));
        $('#terminal-love-bar').css('width', loveValue + '%');

        $('#terminal-trust-value').text(trustValue + ' / 100');
        $('#terminal-trust-state').text(getTrustDescription(trustValue));
        $('#terminal-trust-bar').css('width', trustValue + '%');

        $('#terminal-relationship-value').text(relationshipValue);
        $('#terminal-relationship-state').text('ENUM_VALUE_CONFIRMED');

        $('#terminal-mental-value').text(
            (mentalValue > 0 ? '+' : '') + mentalValue + ' / [-100,100]'
        );
        $('#terminal-mental-state').text(getMentalDescription(mentalValue));
        $('#terminal-mental-bar').css('width', mentalPercentage + '%');

        let sanitySeverity = 'normal';
        if (sanityValue < 20) {
            sanitySeverity = 'danger';
        } else if (sanityValue < 60) {
            sanitySeverity = 'warning';
        }

        let mentalSeverity = 'normal';
        if (Math.abs(mentalValue) > 60) {
            mentalSeverity = 'danger';
        } else if (Math.abs(mentalValue) > 30) {
            mentalSeverity = 'warning';
        }

        updateWarningStyle(
            'terminal-sanity-warning',
            getSanityWarning(sanityValue, commentPrefix),
            sanitySeverity
        );

        updateWarningStyle(
            'terminal-mental-warning',
            getMentalWarning(mentalValue, commentPrefix),
            mentalSeverity
        );

        $('#terminal-boot-status').text('[ OK ]');
        $('#terminal-session-status').text('MVU_LINK_ESTABLISHED');
        $('#terminal-last-sync').text(new Date().toLocaleTimeString());

        return {
            sanity: sanityValue,
            love: loveValue,
            trust: trustValue,
            relationship: relationshipValue,
            mental: mentalValue,
            mentalPercentage: mentalPercentage,
            characterData: characterData
        };
    }

    /* 根据查询字段生成交互结果 */
    function getQueryResult(fieldName) {
        const all_variables = getAllVariables();

        const queryMap = {
            sanity: {
                path: 'stat_data.SanityOfLi',
                fallback: 100,
                format: function (value) {
                    const safeValue = clampTerminalNumber(value, 0, 100, 100);
                    return safeValue + ' :: ' + getSanityDescription(safeValue);
                }
            },
            love: {
                path: 'stat_data.LoveForEthan',
                fallback: 0,
                format: function (value) {
                    const safeValue = clampTerminalNumber(value, 0, 100, 0);
                    return safeValue + ' :: ' + getLoveDescription(safeValue);
                }
            },
            trust: {
                path: 'stat_data.TrustForEthan',
                fallback: 0,
                format: function (value) {
                    const safeValue = clampTerminalNumber(value, 0, 100, 0);
                    return safeValue + ' :: ' + getTrustDescription(safeValue);
                }
            },
            relationship: {
                path: 'stat_data.RelationshipStage',
                fallback: '陌生人',
                format: function (value) {
                    return String(value) + ' :: RELATIONSHIP_STAGE';
                }
            },
            mental_state: {
                path: 'stat_data.EthanMentalState',
                fallback: 0,
                format: function (value) {
                    const safeValue = clampTerminalNumber(value, -100, 100, 0);
                    const sign = safeValue > 0 ? '+' : '';
                    return sign + safeValue + ' :: ' + getMentalDescription(safeValue);
                }
            }
        };

        const selectedQuery = _.get(queryMap, fieldName, _.get(queryMap, 'trust'));
        const rawValue = _.get(all_variables, selectedQuery.path, selectedQuery.fallback);

        return selectedQuery.format(rawValue);
    }

    /* 模拟终端查询反馈 */
    function runTerminalQuery(fieldName) {
        const safeField = String(fieldName || 'trust');
        const commandText = 'query --target=Ethan --field=' + safeField;

        $('.terminal-query').removeClass('active');
        $('.terminal-query[data-field="' + safeField + '"]').addClass('active');

        $('#terminal-live-command').text(commandText);
        $('#terminal-response')
            .stop(true, true)
            .show();

        $('#terminal-response-label').text('[EXEC] ');
        $('#terminal-response-value')
            .addClass('terminal-loading')
            .text('reading stat_data');

        window.setTimeout(function () {
            $('#terminal-response-label').text('[RESULT] ');
            $('#terminal-response-value')
                .removeClass('terminal-loading')
                .text(getQueryResult(safeField));
        }, 420);
    }

    /* 初始化状态栏 */
    async function init() {
        await waitGlobalInitialized('Mvu');

        populateCharacterData();

        $('.terminal-query').on('click', function () {
            const fieldName = String($(this).data('field') || 'trust');
            runTerminalQuery(fieldName);
        });

        $('#terminal-refresh-button').on('click', function () {
            $('#terminal-boot-status').text('[ .. ]');
            $('#terminal-session-status').text('SYNCING');

            window.setTimeout(function () {
                populateCharacterData();
                runTerminalQuery(
                    String($('.terminal-query.active').data('field') || 'trust')
                );
            }, 300);
        });

        $('#terminal-theme-button').on('click', function () {
            $('#ethan-terminal-card').toggleClass('amber-mode');

            const isAmber = $('#ethan-terminal-card').hasClass('amber-mode');
            $(this).text(isAmber ? 'GREEN' : 'AMBER');
        });

        runTerminalQuery('trust');
    }

    /* 使用错误捕获包装初始化流程 */
    $(errorCatched(init));
    </script>
