    <script type="module">
    /* 依据数值返回档位描述 */
    function levelOf(value, table) {
        for (const item of table) {
            if (value <= item.max) return item;
        }
        return _.last(table);
    }

    /* 依据百分比返回进度条配色类 */
    function fillClass(percent) {
        if (percent < 34) return 'mc-fill lv-low';
        if (percent < 71) return 'mc-fill lv-mid';
        return 'mc-fill lv-high';
    }

    function populateCharacterData() {
        const all_variables = getAllVariables();

        /* ==== 读取变量 ==== */
        const shell = _.clamp(_.defaultTo(Number(_.get(all_variables, 'stat_data.ShellOfLi', 75)), 75), 0, 100);
        const love = _.clamp(Number(_.get(all_variables, 'stat_data.LoveForEthan', 0)) || 0, 0, 100);
        const trust = _.clamp(Number(_.get(all_variables, 'stat_data.TrustForEthan', 0)) || 0, 0, 100);
        const mind = _.clamp(_.defaultTo(Number(_.get(all_variables, 'stat_data.EthanMentalState', -10)), -10), -100, 100);
        const stage = _.get(all_variables, 'stat_data.RelationshipStage', '陌生人');

        /* ==== 心率 ← 好感度 ==== */
        const hr = Math.round(58 + love * 0.62);
        const loveLv = levelOf(love, [
            { max: 19, t: '窦性心律，无异常波动。无菌排斥。' },
            { max: 45, t: '轻微窦性心动过速。样本观察期。' },
            { max: 70, t: '心率随特定刺激上升。灰色默契。' },
            { max: 90, t: '心律不齐，诱因明确。原则的裂缝。' },
            { max: 100, t: '心动过速，无药可医。不可替代的例外。' }
        ]);
        $('#mc-hr-num').text(hr + ' bpm');
        $('#mc-hr-raw').text('（' + love + '/100）');
        $('#mc-hr-fill').attr('class', fillClass(love)).css('width', love + '%');
        $('#mc-hr-note').text(loveLv.t);

        /* ==== 血压 ← 外壳值 ==== */
        /* 满值不是理想状态:外壳越完整,压力越高 */
        const sys = Math.round(80 + shell * 0.7);
        const dia = Math.round(50 + shell * 0.45);
        const shellOpen = shell >= 60 && shell < 80 && love >= 91;
        const shellLv = shellOpen
            ? { t: '读数回落。患者第一次主诉疲劳，没有再核对一遍。', c: 'lv-shell-open' }
            : levelOf(shell, [
                { max: 19, t: '循环衰竭。立即留观，不许他自己签出院。', c: 'lv-shell-rebound' },
                { max: 39, t: '读数正常得可疑。衬衫比平时更平整。', c: 'lv-shell-cave' },
                { max: 59, t: '读数正常。患者开始替别人量血压。', c: 'lv-shell-spill' },
                { max: 79, t: '长期轻度高压，患者自认正常。报告核对了三遍。', c: 'lv-shell-tol' },
                { max: 100, t: '高压，读数稳定得像仪器本身。患者称不需要任何人。', c: 'lv-shell-hard' }
            ]);
        $('#mc-bp-num').text(sys + '/' + dia + ' mmHg');
        $('#mc-bp-raw').text('（' + shell + '/100）');
        $('#mc-bp-fill').attr('class', 'mc-fill ' + shellLv.c).css('width', shell + '%');
        $('#mc-bp-note').text(shellLv.t);


        /* ==== 体温 ← 信任值 ==== */
        const temp = (35.6 + trust * 0.022).toFixed(1);
        const trustLv = levelOf(trust, [
            { max: 19, t: '体表冰凉。零信任，一切信息需交叉验证。' },
            { max: 45, t: '低于常温。有限信任，仅限专业领域。' },
            { max: 70, t: '恢复常温。条件信任，可托付案件判断。' },
            { max: 90, t: '体温偏高。深层信任，愿把后背交出。' },
            { max: 100, t: '持续高热。绝对信任，超越体制。' }
        ]);
        $('#mc-t-num').text(temp + ' °C');
        $('#mc-t-raw').text('（' + trust + '/100）');
        $('#mc-t-fill').attr('class', fillClass(trust)).css('width', trust + '%');
        $('#mc-t-note').text(trustLv.t);

        /* ==== 诊断 ← 关系阶段 ==== */
        const stageNote = {
            '陌生人': '初诊。既往史不详，无接触基础。',
            '熟人': '复诊。基本认知已建立，关系停留在表面。',
            '挚友': '长期随访。私人层面坦诚，情感负担可共担。',
            '搭档': '联合治疗。案件协作默契稳定，互为依赖。',
            '恋人': '并发亲密关系。已确认情感承诺，无需再行确诊。',
            '劲敌': '医患关系破裂。羁绊未断，转为对抗性。'
        };
        $('#mc-stage').text(stage);
        $('#mc-stage-note').text(_.get(stageNote, stage, '待确诊。'));

        /* ==== 主治医师自述 ← Ethan 精神状态 ==== */
        const mindLv = levelOf(mind, [
            { max: -61, t: '重度抑郁期', d: '行动迟缓，拒绝交流，自残倾向。诊所由小五维持。' },
            { max: -31, t: '抑郁低谷', d: '沉默、厌食，术中精度下降。烟量增加。' },
            { max: -1, t: '低落波动', d: '尚可运转。尖刻的黑色幽默。' },
