            { max: 30, t: '轻度活跃', d: '精力充沛，幽默感与调情倾向。' },
            { max: 60, t: '躁狂前兆', d: '睡眠减少，思维加速，高风险行为。' },
            { max: 100, t: '躁狂爆发', d: '通宵不眠，判断力受损。' }
        ]);
        const magnitude = Math.abs(mind);
        const halfWidth = (magnitude / 100) * 50;
        const $mindFill = $('#mc-mind-fill');
        if (mind >= 0) {
            $mindFill.attr('class', 'pos').css({ left: '50%', width: halfWidth + '%' });
        } else {
            $mindFill.attr('class', 'neg').css({ left: (50 - halfWidth) + '%', width: halfWidth + '%' });
        }
        $('#mc-mind-num').text((mind > 0 ? '+' : '') + mind);
        $('#mc-mind-state').text(mindLv.t);
        $('#mc-mind-desc').text(mindLv.d);

        /* 异常提示 */
        if (magnitude > 60 || shell < 40) {
            $('#mc-warn').text('⚠ 医嘱：本卡记录存在异常读数，处置需谨慎。').show();
        } else {
            $('#mc-warn').hide();
        }
    }

    async function init() {
        await waitGlobalInitialized('Mvu');
        populateCharacterData();

        /* 点击"备注"展开隐藏批注 */
        $('#mc-toggle').on('click', function () {
            $('#mc-hidden').slideToggle(180);
        });
