        $('#mental-thumb').css('left', Math.max(0, Math.min(100, mentalPercent)) + '%');

        /* 阶段显示 */
        const mentalStage = getMentalStage(mental);
        $('#mental-stage-text').text(mentalStage);

        /* 医嘱 */
        const noteData = getMedicalNote(mentalStage);
        let noteHtml = '';
        $.each(noteData.lines, function(i, line) {
            noteHtml += '<div class="medical-note-line">' + line + '</div>';
        });
        $('#medical-note-content').html(noteHtml);

        /* 关系阶段 */
        $('#rel-stage-value').text(stage);
        $('#rel-stage-def').text(getStageDef(stage));

        /* 序列号 */
        const serial = 'JZ-' + String(Math.floor(Math.random() * 90000) + 10000);
        $('#dossier-serial').text(serial);
    }

    $(errorCatched(init));
    </script>
</head>
